} from '../source/index.js';

const defaultMessage = 'Expected a defined value, got `undefined`';

const throwsWith = (function_: () => void, expected: string): void => {
	let message = 'the call did not throw';

	try {
		function_();
	} catch (error: unknown) {
		assert.ok(error instanceof TypeError);
		message = (error as TypeError).message;
	}

	assert.equal(message, expected);
};

const body = (): void => {
	assert.doesNotThrow(() => assertDefined('defined'));

	// Only `undefined` is rejected, not other falsy or nullish values.
	const definedValues: unknown[] = [null, 0, -0, '', false, Number.NaN, [], Object.create(null)];

	for (const value of definedValues) {
		assert.doesNotThrow(() => assertDefined(value));
	}

	assert.throws(() => assertDefined(undefined), TypeError);
	throwsWith(() => assertDefined(undefined), defaultMessage);

	assert.throws(() => assertDefined(undefined, 'Custom message'), TypeError);
	throwsWith(() => assertDefined(undefined, 'Custom message'), 'Custom message');

	// An explicitly passed `undefined` message falls back to the default.
	throwsWith(() => assertDefined(undefined, undefined), defaultMessage);

	// An empty custom message is used as-is.
	throwsWith(() => assertDefined(undefined, ''), '');

